import sys

def main():
    data = sys.stdin.read().split()
    N = int(data[0]); M = int(data[1])
    S = data[2].strip()
    MOD = 998244353
    NS = 1 << N

    def to_f(mask):
        f = [0]
        for j in range(1, N + 1):
            f.append(f[-1] + ((mask >> (j - 1)) & 1))
        return f

    def to_mask(f):
        mask = 0
        for j in range(1, N + 1):
            if f[j] - f[j - 1]:
                mask |= 1 << (j - 1)
        return mask

    letters = [chr(ord('a') + i) for i in range(26)]
    trans = [[0] * 26 for _ in range(NS)]
    for s in range(NS):
        f = to_f(s)
        for ci, c in enumerate(letters):
            g = [0] * (N + 1)
            for j in range(1, N + 1):
                if S[j - 1] == c:
                    g[j] = f[j - 1] + 1
                else:
                    g[j] = max(g[j - 1], f[j])
            trans[s][ci] = to_mask(g)

    dp = [0] * NS
    dp[0] = 1
    for _ in range(M):
        ndp = [0] * NS
        for s in range(NS):
            v = dp[s]
            if v == 0:
                continue
            tr = trans[s]
            for ci in range(26):
                t = tr[ci]
                ndp[t] += v
        dp = [x % MOD for x in ndp]

    ans = [0] * (N + 1)
    for s in range(NS):
        k = bin(s).count('1')
        ans[k] = (ans[k] + dp[s]) % MOD

    print(' '.join(map(str, ans)))

