from collections import deque

def main():
    data = sys.stdin.read().split()
    N = int(data[0]); M = int(data[1]); S = data[2]
    MOD = 998244353

    def step(P, ch):
        Q = [0] * (N + 1)
        for j in range(1, N + 1):
            best = Q[j - 1]
            if P[j] > best:
                best = P[j]
            v = P[j - 1] + (1 if S[j - 1] == ch else 0)
            if v > best:
                best = v
            Q[j] = best
        return tuple(Q)

    letters = [chr(ord('a') + i) for i in range(26)]
    start = tuple([0] * (N + 1))
    idx = {start: 0}
    rows = [start]
    trans = []
    dq = deque([start])
    # BFS to enumerate reachable states and transitions
    pending = {}
    order = []
    while dq:
        r = dq.popleft()
        order.append(r)
        lst = []
        for ch in letters:
            nr = step(r, ch)
            if nr not in idx:
                idx[nr] = len(rows)
                rows.append(nr)
                dq.append(nr)
            lst.append(idx[nr])
        pending[idx[r]] = lst
    K = len(rows)
    trans = [pending[i] for i in range(K)]

    cnt = [0] * K
    cnt[0] = 1
    for _ in range(M):
        new = [0] * K
        for s in range(K):
            c = cnt[s]
            if c:
                for t in trans[s]:
                    new[t] += c
        cnt = [x % MOD for x in new]

    ans = [0] * (N + 1)
    for s in range(K):
        ans[rows[s][N]] = (ans[rows[s][N]] + cnt[s]) % MOD
    print(" ".join(map(str, ans)))

