from hypothesis import strategies as st

MOD = 998244353


@st.composite
def gen(draw):
    n = draw(st.integers(1, 10))
    m = draw(st.integers(1, 3))  # kept small so brute force in ref stays fast
    mode = draw(st.sampled_from(["random", "same", "sorted", "small"]))
    if mode == "same":
        c = draw(st.sampled_from("abcdefghijklmnopqrstuvwxyz"))
        s = c * n
    elif mode == "sorted":
        letters = draw(st.lists(st.sampled_from("abcdefghijklmnopqrstuvwxyz"),
                                min_size=n, max_size=n))
        s = "".join(sorted(letters))
    elif mode == "small":
        s = "".join(draw(st.lists(st.sampled_from("ab"), min_size=n, max_size=n)))
    else:
        s = "".join(draw(st.lists(st.sampled_from("abcdefghijklmnopqrstuvwxyz"),
                                  min_size=n, max_size=n)))
    return f"{n} {m}\n{s}\n"


def validate(inp):
    toks = inp.split()
    if len(toks) != 3:
        return False
    try:
        n = int(toks[0])
        m = int(toks[1])
    except ValueError:
